+static int jq_query_front_set_pair_supported(struct jq_query_front *q, jv_kind tk, jv_kind kk) {
+
+  q->val_set_start = 0;
+
+  q->val_set_end = 0;
+
+  switch (kk) {
+
+  case JV_KIND_STRING:
+
+    return (tk == JV_KIND_OBJECT || tk == JV_KIND_NULL);
+
+  case JV_KIND_NUMBER:
+
+    return (tk == JV_KIND_ARRAY || tk == JV_KIND_NULL);
+
+  case JV_KIND_OBJECT:
+
+    return (tk == JV_KIND_ARRAY || tk == JV_KIND_NULL);
+
+  case JV_KIND_ARRAY:
+
+  case JV_KIND_NULL:
+
+  case JV_KIND_TRUE:
+
+  case JV_KIND_FALSE:
+
+  case JV_KIND_INVALID:
+
+    return 0;
+
+  default:
+
+    return 0;
+
+  }
+
+}
