+static int jq_query_front_opc_classify_simple(struct jq_query_front *q, opcode op) {
+
+  jq_query_front_opc_capture(q, op);
+
+  switch (op) {
+
+  case LOADK:
+
+    return q->opc_length == 1 ? 1 : 0;
+
+  case DUP:
+
+    return q->opc_length == 1 ? 1 : 0;
+
+  case DUPN:
+
+    return q->opc_length == 1 ? 1 : 0;
+
+  case DUP2:
+
+    return q->opc_length == 1 ? 1 : 0;
+
+  case POP:
+
+    return q->opc_length == 1 ? 1 : 0;
+
+  case INDEX:
+
+    return q->opc_length == 1 ? 1 : 0;
+
+  case INDEX_OPT:
+
+    return q->opc_length == 1 ? 1 : 0;
+
+  case EACH:
+
+    return q->opc_length == 1 ? 1 : 0;
+
+  case EACH_OPT:
+
+    return q->opc_length == 1 ? 1 : 0;
+
+  case INSERT:
+
+    return q->opc_length == 1 ? 1 : 0;
+
+  case APPEND:
+
+    return q->opc_length == 1 ? 1 : 0;
+
+  case BACKTRACK:
+
+    return q->opc_length == 1 ? 1 : 0;
+
+  case JUMP:
+
+    return q->opc_length == 1 ? 1 : 0;
+
+  case JUMP_F:
+
+    return q->opc_length == 1 ? 1 : 0;
+
+  case FORK:
+
+    return q->opc_length == 1 ? 1 : 0;
+
+  case FORK_OPT:
+
+    return q->opc_length == 1 ? 1 : 0;
+
+  case CALL_JQ:
+
+    return q->opc_length == 1 ? 1 : 0;
+
+  case RET:
+
