+static int jq_query_front_utf8_decode_len(struct jq_query_front *q, const char *s) {
+  const char *in;
+  const char *end;
+  int n = 0;
+  q->diag_column = 0;
+  if (s == NULL) {
+    return 0;
+  }
+  in = s;
+  end = s + strlen(s);
+  while (in < end) {
+    int code = 0;
+    const char *nx = jvp_utf8_next(in, end, &code);
+    if (nx == NULL) {
+      q->diag_column = -1;
